--
-- Name: expirar_ventas_y_liberar_boletas(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.expirar_ventas_y_liberar_boletas() RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Marcar ventas vencidas como EXPIRADA (solo si aún estaban pendientes)
  UPDATE ventas
  SET estado_venta = 'EXPIRADA'
  WHERE estado_venta = 'PENDIENTE'
    AND expires_at IS NOT NULL
    AND expires_at < NOW();

  -- Liberar boletas vencidas (si están RESERVADAS y su bloqueo ya pasó)
  UPDATE boletas
  SET
    estado = 'DISPONIBLE',
    venta_id = NULL,
    reserva_token = NULL,
    bloqueo_hasta = NULL,
    cliente_id = NULL
  WHERE estado = 'RESERVADA'
    AND bloqueo_hasta IS NOT NULL
    AND bloqueo_hasta < NOW();
END;
$$;


